mapper.update:
update bargain
seller_counter_offer = #{sellerCounterOffer}, bargain_status = #{bargainStatus}, order_id = #{orderId}, expire_time = #{expireTime}, update_time = #{updateTime},
where id = #{id}

mapper.select:
select b.id, b.seller_id sellerId, b.buyer_id buyerId, b.product_id productId, b.buyer_offer buyerOffer, b.seller_counter_offer sellerCounterOffer, b.bargain_status bargainStatus, b.order_id orderId, b.expire_time expireTime, b.create_time createTime, p.title productTitle, p.images productImages, p.price productPrice, bu.nickname buyerName, su.nickname sellerName from bargain b left join product p on b.product_id = p.id left join user bu on b.buyer_id = bu.id left join user su on b.seller_id = su.id
and b.buyer_id = #{buyerId} and b.seller_id = #{sellerId} and b.bargain_status = #{bargainStatus}
order by b.create_time desc
